{
  "items": [
    {
      "name": "DividedPowers.RatAlgebra.dpow_eq_inv_fact_smul",
      "module_name": "Mathlib.RingTheory.DividedPowers.RatAlgebra",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : CommSemiring R] (I : Ideal R) [inst_1 : Algebra ℚ R] (hI : DividedPowers I) {n : ℕ} {x : R},\n  x ∈ I → hI.dpow n x = Ring.inverse ↑n.factorial • x ^ n"
    },
    {
      "name": "Polynomial.factorial_smul_hasseDeriv",
      "module_name": "Mathlib.Algebra.Polynomial.HasseDeriv",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R] (k : ℕ), ⇑(k.factorial • Polynomial.hasseDeriv k) = (⇑Polynomial.derivative)^[k]"
    },
    {
      "name": "DividedPowers.factorial_mul_dpow_eq_pow",
      "module_name": "Mathlib.RingTheory.DividedPowers.Basic",
      "kind": "theorem",
      "type": "∀ {A : Type u_1} [inst : CommSemiring A] {I : Ideal A} {a : A} (hI : DividedPowers I) {n : ℕ},\n  a ∈ I → ↑n.factorial * hI.dpow n a = a ^ n"
    },
    {
      "name": "DividedPowers.dpow_smul",
      "module_name": "Mathlib.RingTheory.DividedPowers.Basic",
      "kind": "theorem",
      "type": "∀ {A : Type u_1} [inst : CommSemiring A] {I : Ideal A} {a b : A} (hI : DividedPowers I) {n : ℕ},\n  a ∈ I → hI.dpow n (b • a) = b ^ n • hI.dpow n a"
    },
    {
      "name": "DividedPowers.OfInvertibleFactorial.dpow",
      "module_name": "Mathlib.RingTheory.DividedPowers.RatAlgebra",
      "kind": "definition",
      "type": "{A : Type u_1} → [inst : CommSemiring A] → (I : Ideal A) → [DecidablePred fun x => x ∈ I] → ℕ → A → A"
    }
  ]
}
